def get_top_strengths(planets_data, n=6):
    """各惑星の星座から得意なことを集め、頻度・優先度でランク付け"""
    from collections import Counter
    score = Counter()
    weights = {"Sun": 3, "Moon": 3, "Mercury": 2, "Venus": 2, "Mars": 2, "Jupiter": 1, "Saturn": 1}
    for pname, w in weights.items():
        if pname not in planets_data:
            continue
        sign = planets_data[pname]["sign"]
        for s in STRENGTHS_BY_SIGN.get(sign, []):
            score[s] += w
    seen = []
    for s, _ in score.most_common():
        if s not in seen:
            seen.append(s)
        if len(seen) >= n:
            break
    return seen


def get_top_challenges(planets_data, n=4):
    """主要惑星の課題テキストを集める"""
    result = []
    challenge_map = {
        "Sun": SUN_CHALLENGE, "Moon": MOON_CHALLENGE,
        "Mercury": MERCURY_CHALLENGE, "Venus": VENUS_CHALLENGE, "Mars": MARS_CHALLENGE,
    }
    weights = [("Sun",3),("Moon",3),("Mercury",2),("Venus",2),("Mars",2)]
    for pname, _ in weights:
        sk = planets_data.get(pname, {}).get("sign")
        if sk and pname in challenge_map:
            txt = challenge_map[pname].get(sk,"")
            if txt:
                result.append(txt)
        if len(result) >= n:
            break
    return result


