# HTML レポート生成
# ============================================================

_HTML_CSS = """
@import url('https://fonts.googleapis.com/css2?family=Noto+Serif+JP:wght@300;400;500;600&family=Noto+Sans+JP:wght@300;400;500&family=Cormorant+Garamond:ital,wght@0,300;0,400;1,300;1,400&display=swap');

:root{
  --bg:    #FAF7F2;
  --bg2:   #F3EDE4;
  --bg3:   #E8DED0;
  --panel: #FFFFFF;
  --night: #0B0D1C;
  --navy:  #1C1A2E;
  --gold:  #7A5E1A;
  --gold-l:#9A7828;
  --gold-d:#5A4210;
  --rose:  #8A4858;
  --rose-l:#A06070;
  --lav:   #5A4890;
  --lav-l: #7060A8;
  --text-d:#1C1A2E;
  --text-m:#1C1A2E;
  --text-l:#4A4860;
  --warn:  #804820;
  --serif: "Noto Serif JP","Cormorant Garamond",serif;
  --sans:  "Noto Sans JP",sans-serif;
  --en:    "Cormorant Garamond",serif;
}
*{box-sizing:border-box;margin:0;padding:0;}
html{scroll-behavior:smooth;}
body{background:var(--bg);color:var(--text-d);font-family:var(--sans);
     font-weight:300;font-size:16px;line-height:1.9;
     -webkit-font-smoothing:antialiased;}
.container{max-width:820px;margin:0 auto;padding:0 2rem;}

/* ── Nav ── */
.nav{position:sticky;top:0;
     background:rgba(250,247,242,0.95);
     backdrop-filter:blur(16px);
     border-bottom:1px solid var(--bg3);
     z-index:100;display:flex;align-items:center;gap:2px;
     padding:.5rem 1.8rem;overflow-x:auto;}
.nav::-webkit-scrollbar{display:none;}
.nav-name{color:var(--gold);font-family:var(--serif);font-size:.82rem;
          font-weight:400;white-space:nowrap;margin-right:.8rem;flex-shrink:0;
          letter-spacing:.1em;}
.nav a{color:var(--text-l);text-decoration:none;font-size:.75rem;
       white-space:nowrap;padding:.22rem .62rem;border-radius:2px;
       border:1px solid transparent;transition:all .2s;
       flex-shrink:0;font-weight:300;letter-spacing:.04em;}
.nav a:hover{border-color:rgba(184,146,58,.4);color:var(--gold);}

/* ── Hero ── */
.hero{text-align:center;padding:6rem 2rem 5rem;
      background:linear-gradient(180deg, var(--night) 0%, #0F1228 100%);}
.hero-ornament{display:flex;align-items:center;justify-content:center;gap:1.2rem;
               margin-bottom:2.2rem;}
.hero-ornament span{color:var(--gold-d);font-size:.72rem;letter-spacing:.8em;}
.hero-ornament::before,.hero-ornament::after{content:'';flex:1;max-width:100px;
  height:1px;background:linear-gradient(to right,transparent,rgba(184,146,58,.45));}
.hero-ornament::after{transform:scaleX(-1);}
.hero h1{font-family:var(--serif);font-size:2.55rem;color:#EDD898;
         letter-spacing:.18em;font-weight:300;margin-bottom:.8rem;line-height:1.45;}
.hero .subtitle{font-family:var(--en);font-size:.9rem;font-style:italic;
                color:rgba(250,247,242,.5);margin-bottom:3.2rem;letter-spacing:.1em;}
.hero .hero-name{font-family:var(--serif);font-size:1.75rem;color:#FAF7F2;
                 font-weight:400;margin-bottom:.85rem;letter-spacing:.1em;}
.hero .birth-box{color:rgba(250,247,242,.6);font-size:.82rem;
                 background:rgba(255,255,255,.05);
                 border:1px solid rgba(184,146,58,.2);
                 display:inline-block;padding:.45rem 2.2rem;
                 border-radius:2px;margin-bottom:3.2rem;letter-spacing:.04em;}
.hero .planet-syms{color:rgba(184,146,58,.5);font-size:1.15rem;letter-spacing:.55em;}

/* ── Section ── */
.sec{padding:5rem 0;border-top:1px solid var(--bg3);}
.sec-eyebrow{display:block;font-family:var(--en);font-size:.72rem;font-style:italic;
             letter-spacing:.25em;color:var(--gold);
             margin-bottom:.55rem;font-weight:300;}
.sec-title{font-family:var(--serif);font-size:1.45rem;color:var(--navy);
           letter-spacing:.07em;margin-bottom:.45rem;font-weight:400;}
.sec-sub{color:var(--text-l);font-size:.82rem;margin-bottom:2.8rem;letter-spacing:.03em;}

/* ── Chart ── */
.chart-layout{display:flex;gap:2.5rem;align-items:flex-start;}
.chart-img{width:330px;flex-shrink:0;border-radius:4px;
           border:1px solid var(--bg3);display:block;}
.p-list{flex:1;}
.p-item{display:flex;align-items:center;gap:.7rem;padding:.55rem .9rem;
        background:var(--bg2);
        border:1px solid var(--bg3);
        border-radius:2px;margin-bottom:.35rem;transition:background .2s;}
.p-item:hover{background:var(--bg3);}
.p-sym{font-size:1.18rem;width:1.6rem;text-align:center;flex-shrink:0;}
.p-jp{font-size:.8rem;font-weight:500;width:2.8rem;flex-shrink:0;
      color:var(--text-d);letter-spacing:.03em;}
.p-sign{font-size:.9rem;flex:1;color:var(--text-d);}
.p-deg{font-size:.72rem;color:var(--text-l);}

/* ── Planet Section ── */
.planet-sec{padding:5rem 0;border-top:1px solid var(--bg3);position:relative;}
.planet-sec::before{content:'';position:absolute;top:0;left:0;width:2px;height:100%;
                    background:linear-gradient(to bottom,var(--pc) 0%,transparent 85%);}
.pl-header{display:flex;align-items:baseline;gap:1rem;margin-bottom:.55rem;flex-wrap:wrap;}
.pl-sym{font-size:2.1rem;line-height:1;}
.pl-name{font-family:var(--serif);font-size:1.6rem;font-weight:400;
         letter-spacing:.06em;color:var(--navy);}
.pl-sign{font-family:var(--serif);font-size:1.15rem;color:var(--gold);
         margin-left:auto;font-weight:300;letter-spacing:.04em;}
.pl-theme{font-family:var(--en);font-size:.8rem;font-style:italic;
          color:var(--lav);margin-bottom:2.2rem;padding-left:.9rem;
          letter-spacing:.06em;border-left:2px solid rgba(136,120,176,.4);}

/* ── Intro box ── */
.intro-box{background:var(--panel);
           border:1px solid var(--bg3);
           border-radius:2px;padding:1.8rem 2rem;margin:0 0 2.5rem;
           box-shadow:0 2px 12px rgba(0,0,0,.04);}
.intro-ttl{font-family:var(--serif);font-size:.95rem;font-weight:500;color:var(--gold);
           margin-bottom:1.2rem;letter-spacing:.06em;}
.intro-para{font-size:.91rem;color:var(--text-m);line-height:1.98;margin-bottom:.85rem;}
.intro-para:last-child{margin-bottom:0;}
.intro-2col{display:grid;grid-template-columns:1fr 1fr;gap:1.5rem;margin-top:1.4rem;}
.intro-col{background:var(--bg2);border-radius:2px;
           padding:1.2rem 1.4rem;border:1px solid var(--bg3);}
.intro-col-ttl{font-family:var(--serif);font-size:.84rem;font-weight:500;
               color:var(--navy);margin-bottom:.75rem;letter-spacing:.04em;}

/* ── Your sign title ── */
.your-sign-ttl{font-family:var(--serif);font-size:1.05rem;font-weight:400;
               color:var(--navy);letter-spacing:.08em;margin:2.5rem 0 1rem;
               padding-left:1rem;border-left:3px solid var(--pc);}

/* ── Keyword box ── */
.kw-box{background:var(--bg2);border-left:4px solid var(--pc);
        padding:1rem 1.6rem;border-radius:0 2px 2px 0;margin-bottom:2rem;}
.kw-text{font-family:var(--en);font-size:1.1rem;font-style:italic;font-weight:300;
         color:var(--navy);line-height:1.65;}

/* ── Body ── */
.body-para{margin-bottom:1.65rem;}
.body-lead{font-size:.98rem;font-weight:500;color:var(--navy);
           margin-bottom:.42rem;line-height:1.75;}
.body-rest{font-size:.9rem;color:var(--text-m);line-height:1.98;}

/* ── Challenge box ── */
.challenge-box{background:rgba(176,120,136,.05);
               border:1px solid rgba(176,120,136,.2);
               border-radius:2px;padding:1.1rem 1.5rem;margin-top:1.8rem;}
.challenge-ttl{font-size:.78rem;font-weight:500;color:var(--rose);
               margin-bottom:.5rem;letter-spacing:.06em;}
.challenge-txt{font-size:.88rem;color:var(--text-m);line-height:1.9;}

/* ── Sign note ── */
.sign-note{background:var(--panel);
           border:1px solid var(--bg3);
           border-radius:2px;padding:1.2rem 1.6rem;margin-top:2rem;}
.sign-note-ttl{font-family:var(--serif);font-size:.87rem;color:var(--gold);
               font-weight:500;margin-bottom:.6rem;letter-spacing:.04em;}
.sign-note-txt{font-size:.9rem;color:var(--text-m);line-height:1.9;}

/* ── Summary ── */
.summary-sec{padding:5.5rem 0 8rem;border-top:1px solid var(--bg3);}
.pg-grid-wrap{margin-bottom:3rem;}
.pg-row{display:grid;gap:.6rem;margin-bottom:.6rem;}
.pg-row-4{grid-template-columns:repeat(4,1fr);}
.pg-row-3{grid-template-columns:repeat(3,1fr);}
.pg-card{background:var(--panel);
         border:1px solid var(--bg3);
         border-radius:2px;overflow:hidden;
         text-decoration:none;display:block;transition:all .2s;
         box-shadow:0 1px 6px rgba(0,0,0,.04);}
.pg-card:hover{border-color:rgba(184,146,58,.4);transform:translateY(-2px);
               box-shadow:0 4px 16px rgba(0,0,0,.08);}
.pg-card-hd{padding:.38rem .7rem;font-size:.7rem;font-weight:500;
            color:#FFF;background:var(--pc);letter-spacing:.03em;}
.pg-card-bd{padding:.6rem .7rem;}
.pg-sign{font-family:var(--serif);font-size:.9rem;font-weight:400;
         color:var(--navy);margin-bottom:.2rem;}
.pg-kw{font-size:.67rem;color:var(--text-l);line-height:1.4;}

/* ── Synthesis ── */
.synthesis-box{border:1px solid var(--bg3);border-radius:2px;
               overflow:hidden;margin-bottom:2.5rem;
               box-shadow:0 2px 12px rgba(0,0,0,.05);}
.synthesis-hd{background:linear-gradient(135deg,#1A1E3A,#0F1228);
              border-bottom:1px solid rgba(184,146,58,.15);
              padding:1.2rem 1.8rem;display:flex;align-items:center;gap:.8rem;}
.synthesis-hd-ttl{font-family:var(--serif);font-size:1.08rem;color:#EDD898;
                  font-weight:400;letter-spacing:.08em;}
.synthesis-body{padding:1.8rem 2rem;background:var(--panel);}
.synthesis-para{font-size:.93rem;color:var(--text-m);line-height:2.05;
                margin-bottom:1.25rem;}
.synthesis-para:last-child{margin-bottom:0;}
.synthesis-para strong{color:var(--navy);font-weight:500;}

/* ── Strengths ── */
.strengths-box{background:var(--panel);
               border:1px solid rgba(136,120,176,.2);
               border-radius:2px;overflow:hidden;margin-bottom:1.8rem;}
.strengths-hd{background:rgba(136,120,176,.07);padding:1rem 1.8rem;
              font-family:var(--serif);font-size:.98rem;color:var(--lav);
              font-weight:400;letter-spacing:.06em;}
.strengths-grid{display:grid;grid-template-columns:1fr 1fr;
                gap:.5rem;padding:1.4rem 1.8rem;}
.strength-item{display:flex !important;align-items:flex-start;gap:.5rem;
               font-size:.72rem !important;color:var(--text-d);line-height:1.65 !important;}
.strength-item::before{content:'◆';color:var(--lav);font-size:.6rem;
                        margin-top:.45rem;flex-shrink:0;}

/* ── Caution ── */
.caution-box{background:var(--panel);
             border:1px solid rgba(176,120,136,.2);
             border-radius:2px;overflow:hidden;}
.caution-hd{background:rgba(176,120,136,.06);padding:1rem 1.8rem;
            font-family:var(--serif);font-size:.98rem;color:var(--rose);
            font-weight:400;letter-spacing:.06em;}
.caution-grid{display:grid;grid-template-columns:1fr 1fr;
              gap:.5rem;padding:1.4rem 1.8rem;}
.caution-item{display:flex !important;align-items:flex-start;gap:.5rem;
              font-size:.72rem !important;color:var(--text-m);line-height:1.7 !important;}
.caution-item::before{content:'△';color:var(--rose);font-size:.6rem;
                       margin-top:.4rem;flex-shrink:0;}

/* ── Footer ── */
footer{background:var(--night);border-top:1px solid rgba(184,146,58,.1);
       padding:3.5rem 2rem;text-align:center;}
.ft-ornament{color:var(--gold-d);letter-spacing:.6em;margin-bottom:1.2rem;font-size:1rem;}
.ft-msg{color:rgba(250,247,242,.35);font-size:.85rem;line-height:2;
        font-family:var(--en);font-weight:300;font-style:italic;}

/* ── Responsive ── */
@media(max-width:640px){
  .hero h1{font-size:1.7rem;letter-spacing:.1em;}
  .chart-layout{flex-direction:column;}
  .chart-img{width:100%;}
  .pg-row-4{grid-template-columns:repeat(2,1fr);}
  .pg-row-3{grid-template-columns:repeat(2,1fr);}
  .intro-2col{grid-template-columns:1fr;}
  .strengths-grid,.caution-grid{grid-template-columns:1fr;}
  .pl-sign{width:100%;margin-left:0;}
}

/* ── ビジュアル要素：キーワードカード ── */
.keyword-card{
  background:linear-gradient(135deg,#FAF5EE 0%,#F3EDE0 100%);
  border:1px solid #D8C8A0;border-left:4px solid #8A6030;
  padding:1.4rem 1.6rem;margin-bottom:1.4rem;border-radius:2px;
}
.kc-label{font-family:var(--en);font-size:.7rem;font-style:italic;
          letter-spacing:.18em;color:#8A6030;margin-bottom:.5rem;}
.kc-text{font-family:var(--serif);font-size:1.18rem;font-weight:500;
         color:#1C1A2E;line-height:1.7;letter-spacing:.04em;}

/* ── ビジュアル要素：サインタグ ── */
.sign-tags{display:flex;flex-wrap:wrap;gap:.5rem;margin-bottom:1.6rem;}
.sign-tag{display:inline-block;padding:.28rem .8rem;
          background:rgba(138,96,48,.08);border:1px solid rgba(138,96,48,.25);
          border-radius:20px;font-size:.74rem;color:#6A4818;
          letter-spacing:.05em;font-family:var(--sans);font-weight:400;}

/* ── ビジュアル要素：番号付きサブセクション ── */
.sub-section{
  margin-top:3.2rem;padding-top:2.2rem;padding-bottom:1.6rem;
  border-top:2px solid #C8A86E;
}
.sub-section:first-of-type{
  margin-top:.8rem;padding-top:0;border-top:none;
}
.sub-section:last-of-type{padding-bottom:.6rem;}
.sub-head{
  display:flex;align-items:center;gap:.55rem;
  margin-bottom:1.1rem;
}
.sub-num{
  font-family:var(--serif);font-size:1.2rem;
  font-style:normal;font-weight:600;color:#8A6030;
  line-height:1;letter-spacing:.02em;
}
.sub-label{
  font-family:var(--serif);font-size:1.2rem;
  font-weight:700;color:#1C1A2E;
  letter-spacing:.05em;line-height:1.4;
}
.sub-body p{
  font-size:.91rem;color:var(--text-m);line-height:2.1;
  margin-bottom:.15rem;
}
.sub-body p:last-child{margin-bottom:0;}
.sub-body p strong{font-weight:600;color:#2A2840;}

/* ── Print / PDF ── */
@media print{
  /* ナビ・ボタン非表示 */
  .nav{display:none !important;}
  button,.btn{display:none !important;}

  /* 全体背景を白に */
  body{background:#fff !important;}
  *{-webkit-print-color-adjust:exact;print-color-adjust:exact;}

  /* ヒーロー：暗背景→淡クリーム */
  .hero{
    background:#F5F0E8 !important;
    color:#1C1A2E !important;
    border-bottom:2px solid #8A6030;
  }
  .hero h1,.hero-name,.hero h2{color:#1C1A2E !important;}
  .hero-ornament span{color:#7A5020 !important;}
  .hero-rule{background:#8A6030 !important;}
  .hero-sub,.hero-date,.hero-loc{color:#4A4860 !important;}
  .hero-label{color:#7A5020 !important;}

  /* overview（暗帯）→淡色に */
  .overview{background:#F0EBE0 !important;}
  .overview-inner{color:#1C1A2E !important;border-left-color:#8A6030 !important;}

  /* テキスト濃度を上げる */
  .sec-planet,.sec-intro,.p-deg,.text-l,
  .nav-name,.pg-kw{color:#5A5870 !important;}

  /* シャドウ除去・枠線を薄く */
  .section,.chart-card,.pg-card,.synthesis-box,
  .strengths-box,.caution-box{
    box-shadow:none !important;
    border:1px solid #D8D0C0 !important;
  }
  .kw-box{border-left-color:#8A6030 !important;}
  .challenge-note{border-left-color:#8A6030 !important;}
  .hoshi-note{border-left-color:#5A4890 !important;}
  /* ビジュアル要素の印刷調整 */
  .keyword-card{
    background:#F5EFE0 !important;
    border-color:#B89858 !important;
    border-left-color:#7A5018 !important;
  }
  .kc-label{color:#7A5018 !important;}
  .kc-text{color:#1C1A2E !important;}
  .sign-tag{
    background:#F0E8D8 !important;
    border-color:#B89858 !important;
    color:#5A3818 !important;
  }
  .sub-num{color:#7A5018 !important;}
  .sub-bullet{color:#7A5018 !important;}
  .sub-section{page-break-inside:avoid;border-top-color:#B89858 !important;}

  /* ページ折り返し制御 */
  .planet-sec,.sec,.summary-sec,.section,
  .synthesis-box,.strengths-box,.caution-box,
  .keyword-card,.hoshi-note,.challenge-note,
  .aspect-item,.lc-card{
    page-break-inside:avoid;
    break-inside:avoid;
  }
}
"""


SUN_HOSHI = {
    "Ari": "あなたの輝きは、迷わず踏み出すその一歩にあります。考えすぎる前に動き、失敗しても立て直せる力がもともと備わっています。「完璧になってから」ではなく「まず始めてから整える」を人生の合言葉にしてみてください。あなたが先頭に立つだけで、周りの空気はすっと動き始めます。",
    "Tau": "本当に大切なものをゆっくり選び取る目が、あなたの一番の財産です。焦らなくていい、急がなくていい——あなたのペースで積み重ねたものは、誰にも揺るがせない確かさになります。心地よさを大切にすることは怠慢ではなく、あなたらしく生きる知恵です。豊かな感覚をもっと信頼してください。",
    "Gem": "「まず話す、あとで整える」を基本スタンスに。情報を集めすぎて動けなくなる前に、小さくでも形にすることを優先してください。あなたの幅広い興味は、人や情報を結びつける独自の視点を生み出します。それを堂々と活かす場を、自分から作りにいきましょう。",
    "Can": "人の痛みをそっと受け止められる深い感受性——そこに、あなたの強さが宿っています。感じやすさは弱さではなく、生まれ持った才能のひとつ。大切な人と築く安心感の中で、いちばん輝く傾向があります。自分を守りながら、愛することを恐れないでください。",
    "Leo": "あなたが本気で楽しんでいるとき、周りは自然と元気をもらいます。自分を表現することへの照れや遠慮は、少しずつ手放してください。舞台の中心に立つことは、わがままではなく、あなたに与えられた使命です。心からの喜びをもっと大きく生きていい。",
    "Vir": "細部に気づける目と、物事を丁寧に整える手が、あなたを本当に必要とされる人にします。完璧でなくてもいい、「十分によくできた」を認める練習をしてみてください。誠実さと誠意は必ず届きます。自分への批判的な声より、積み上げてきたものへの誇りを先に見てください。",
    "Lib": "あなたが場の空気を読んで調和を作る力は、稀有な才能です。でも、誰かに合わせ続けることで自分を見失わないように。自分の意見や好みを「わがまま」と思わず、正直に出すことが、より深い関係をつくります。美しいものを選ぶ直感を、人生全体に活かしてください。",
    "Sco": "あなたには物事の表面だけでなく、その奥に流れる本質を見抜く力があります。深く愛し、深く傷つくことも、あなたの人生を豊かにする経験です。執着と手放しの間で揺れるとき、それは変容の始まりです。恐れずに変わる自分を受け入れてください。",
    "Sag": "あなたの人生は、地平線の向こうを常に目指す冒険です。哲学や旅、学びへの飢えを大切にしてください。ひとつの場所やひとつの答えに縛られなくていい。広い視野で世界を見渡しながら、あなただけの真実を探し続けることが、最も輝かしい生き方です。",
    "Cap": "コツコツと積み上げることへの誠実さが、あなたの人生を確かなものにします。遠回りに見えても、丁寧に歩んだ道は必ず形に残ります。結果を急ぎすぎず、プロセスそのものを誇りにしてください。責任感の強さは武器ですが、自分へのやさしさも忘れずに。",
    "Aqu": "あなたの個性は、時代の少し先を行くビジョンにあります。みんなと同じでなくていい、あなたの「変わった視点」がやがて誰かの道を照らします。孤独を感じるときも、それはあなたが本物の自分でいようとしている証拠です。理想を諦めず、淡々と前へ進んでください。",
    "Pis": "夢と現実のあいだに橋をかける、繊細な感受性が宿っています。その豊かさは才能であり、創造の源。境界線があいまいになりやすい分、自分だけの静かな時間を大切にしてください。直感を信じることで、言葉では説明できない正しさへたどり着けます。",
}

