# ============================================================
# メイン処理
# ============================================================

def generate_report(name, year, month, day, hour, minute, city,
                    lat=None, lng=None, tz_str="Asia/Tokyo", output_dir=None):
    print(f"\n✨ {name} さんの星読みレポートを生成中...\n")

    if lat is not None and lng is not None:
        subject = AstrologicalSubject(
            name, year, month, day, hour, minute,
            lng=lng, lat=lat, tz_str=tz_str, online=False,
            houses_system_identifier="K",
        )
    else:
        subject = AstrologicalSubject(name, year, month, day, hour, minute, city, "JP",
                                      houses_system_identifier="K")

    planets_data = {}
    for pn in ["Sun","Moon","Mercury","Venus","Mars","Jupiter","Saturn"]:
        obj = getattr(subject, pn.lower())
        planets_data[pn] = {
            "sign":      obj.sign,
            "position":  obj.position,
            "abs_pos":   obj.abs_pos,
            "retrograde":obj.retrograde,
        }

    print("🪐 惑星位置:")
    for pn, d in planets_data.items():
        jp   = PLANET_JP[pn]
        sign = SIGN_MAP.get(d["sign"], d["sign"])
        retro= "  ℞（逆行）" if d["retrograde"] else ""
        print(f"  {PLANET_SYMBOL[pn]} {jp}: {sign}  {d['position']:.1f}°{retro}")

    # チャート画像
    with tempfile.NamedTemporaryFile(suffix=".png", delete=False) as f:
        chart_path = f.name
    generate_chart(planets_data, name, chart_path)
    print("\n📊 チャート画像を生成しました")

    # 適職算出
    top_jobs = get_top_jobs(planets_data, n=6)

    # PowerPoint
    prs = Presentation()
    prs.slide_width  = Inches(10)
    prs.slide_height = Inches(7.5)

    birth_info = f"{year}年{month}月{day}日　{hour:02d}:{minute:02d}　／　{city}"

    slide_title(prs, name, birth_info)
    slide_chart(prs, chart_path, planets_data)

    # 太陽・月・水星・金星・火星
    for pn, db in [("Sun",     SUN_PERSONALITY),
                   ("Moon",    MOON_PERSONALITY),
                   ("Mercury", MERCURY_PERSONALITY),
                   ("Venus",   VENUS_PERSONALITY),
                   ("Mars",    MARS_PERSONALITY)]:
        sk = planets_data[pn]["sign"]
        content = db.get(sk, {"keyword": "特別な配置", "body": "ユニークな星の配置です。"})
        slide_planet(prs, pn, sk, content)

    # 木星・土星
    slide_jupiter_saturn(prs, "Jupiter", planets_data["Jupiter"]["sign"],
                         JUPITER_PERSONALITY,
                         JUPITER_SIGN.get(planets_data["Jupiter"]["sign"], ""))
    slide_jupiter_saturn(prs, "Saturn",  planets_data["Saturn"]["sign"],
                         SATURN_PERSONALITY,
                         SATURN_SIGN.get(planets_data["Saturn"]["sign"], ""))

    # 総合まとめ
    slide_summary(prs, name, planets_data, top_jobs)

    safe_name = name.replace("/", "_").replace("\\", "_")
    filename = f"{safe_name}_星読みレポート.pptx"
    output = os.path.join(output_dir, filename) if output_dir else filename
    prs.save(output)
    os.remove(chart_path)

    print(f"\n✅ レポートを保存しました: {output}")
    return output


